import type { DocumentPage } from "@/lib/types";

export type TemplateSource = {
  title: string;
  pages: DocumentPage[];
  fileName?: string;
};

export type ReviewQuestion = {
  question: string;
  answer: string;
  rule: "definition-is" | "definition-means" | "term-colon";
  source: string;
};

const DISCLAIMER =
  "Formatted from your extracted text with a fixed template. These notes were not generated by AI, and no new facts were added.";

const PRONOUN = /^(this|that|it|there|these|those|he|she|they|the following)\b/i;

export function generateReviewQuestions(text: string): ReviewQuestion[] {
  const questions: ReviewQuestion[] = [];
  const seen = new Set<string>();
  const lines = text
    .split(/\n+/)
    .map((line) => line.trim())
    .filter(Boolean);
  for (const line of lines) {
    const sentence = line.replace(/\s+/g, " ").replace(/[.]+$/, "");
    const isMatch = /^([A-Z][^.]{1,70}?) is ([^.]+)$/.exec(sentence);
    const meansMatch = /^([A-Z][^.]{1,70}?) means ([^.]+)$/.exec(sentence);
    const colonMatch = /^([^:]{2,60}):\s+(.+)$/.exec(sentence);
    let next: ReviewQuestion | null = null;
    if (isMatch?.[1] && isMatch[2] && !PRONOUN.test(isMatch[1]) && isMatch[1].split(/\s+/).length <= 6) {
      next = { question: `What is ${isMatch[1].trim()}?`, answer: isMatch[2].trim(), rule: "definition-is", source: line };
    } else if (meansMatch?.[1] && meansMatch[2] && !PRONOUN.test(meansMatch[1])) {
      next = { question: `What does ${meansMatch[1].trim()} mean?`, answer: meansMatch[2].trim(), rule: "definition-means", source: line };
    } else if (colonMatch?.[1] && colonMatch[2] && colonMatch[1].split(/\s+/).length <= 8) {
      next = { question: `What is ${colonMatch[1].trim()}?`, answer: colonMatch[2].trim(), rule: "term-colon", source: line };
    }
    if (next && !seen.has(next.question)) {
      seen.add(next.question);
      questions.push(next);
    }
    if (questions.length >= 12) break;
  }
  return questions;
}

function blocksFromPages(pages: DocumentPage[]) {
  return pages.flatMap((page) => {
    const chunks = page.text
      .split(/\n{2,}/)
      .map((chunk) => chunk.trim())
      .filter(Boolean);
    return chunks.map((text) => ({ text, label: page.label, method: page.method }));
  });
}

function sourceBanner(source: TemplateSource) {
  const file = source.fileName ? ` File: ${source.fileName}.` : "";
  return `# ${source.title}\n\n${DISCLAIMER}${file}\n`;
}

export function structuredLectureNotes(source: TemplateSource) {
  const blocks = blocksFromPages(source.pages);
  const lines = [sourceBanner(source), "## Notes"];
  if (blocks.length === 0) lines.push("\nNo extracted text was available. Paste your notes below.\n");
  for (const block of blocks) {
    const short = block.text.length < 70 && !/[.!?]$/.test(block.text);
    if (short) lines.push(`\n### ${block.text}\n\nSource: ${block.label} (${block.method})`);
    else {
      const sentences = block.text.split(/(?<=[.!?])\s+/).filter(Boolean);
      lines.push(`\n### ${block.label}`);
      for (const sentence of sentences) lines.push(`- ${sentence}`);
    }
  }
  const takeaways = blocks
    .map((block) => block.text.split(/(?<=[.!?])\s+/)[0])
    .filter((sentence): sentence is string => Boolean(sentence))
    .slice(0, 6);
  lines.push("\n## Key takeaways");
  if (takeaways.length === 0) lines.push("\n- Add the points you want to remember.");
  for (const sentence of takeaways) lines.push(`- ${sentence}`);
  return lines.join("\n").trim();
}

export function cornellNotes(source: TemplateSource) {
  const blocks = blocksFromPages(source.pages);
  const lines = [sourceBanner(source), "## Cornell notes\n", "| Cue | Notes |", "| --- | --- |"];
  for (const block of blocks) {
    const cue = block.text.split(/\s+/).slice(0, 6).join(" ");
    const notes = block.text.replace(/\|/g, "/").replace(/\n/g, " ");
    lines.push(`| ${cue} | ${notes} _(${block.label}, ${block.method})_ |`);
  }
  if (blocks.length === 0) lines.push("|  | Paste notes here. |");
  const sentences = blocks.flatMap((block) => block.text.split(/(?<=[.!?])\s+/)).filter(Boolean);
  const summary = [sentences[0], sentences[sentences.length - 1]].filter(Boolean).join(" ");
  lines.push("\n## Summary\n", summary || "Write a short summary in your own words.");
  return lines.join("\n").trim();
}

export function outlineNotes(source: TemplateSource) {
  const lines = [sourceBanner(source), "## Outline"];
  for (const page of source.pages) {
    lines.push(`\n## ${page.label}`);
    for (const raw of page.text.split("\n")) {
      const line = raw.trim();
      if (!line) continue;
      const indent = raw.match(/^\s*/)?.[0].length ?? 0;
      if (indent >= 4 || /^[-*\d]/.test(line)) lines.push(`  - ${line.replace(/^[-*\d.)\s]+/, "")}`);
      else if (line.length < 80) lines.push(`\n### ${line}`);
      else lines.push(`- ${line}`);
    }
    lines.push(`\n_Text source: ${page.method}._`);
  }
  return lines.join("\n").trim();
}

export function studyGuide(source: TemplateSource) {
  const text = source.pages.map((page) => page.text).join("\n");
  const questions = generateReviewQuestions(text);
  const lines = [sourceBanner(source), "## Terms\n"];
  const terms = questions.filter((item) => item.rule === "term-colon" || item.rule === "definition-is");
  if (terms.length === 0) lines.push("No term patterns were found. Add terms as `Term: definition`.\n");
  for (const term of terms) {
    const name = term.question.replace(/^What is /, "").replace(/\?$/, "");
    lines.push(`- **${name}:** ${term.answer}`);
  }
  lines.push("\n## Topics");
  for (const page of source.pages) {
    if (page.text.trim()) lines.push(`\n### ${page.label}\n\n${page.text.trim()}\n\n_Extracted by ${page.method}._`);
  }
  lines.push("\n## Review prompts\n");
  lines.push("These prompts copy phrases from your text using a visible rule. Edit them. They are not AI questions.\n");
  if (questions.length === 0) lines.push("- Add your own question.");
  for (const question of questions) lines.push(`- ${question.question}\n  - Answer from your text: ${question.answer}`);
  return lines.join("\n").trim();
}

export function flashcardNotes(source: TemplateSource) {
  const text = source.pages.map((page) => page.text).join("\n");
  const questions = generateReviewQuestions(text);
  const lines = [
    sourceBanner(source),
    "## Flashcards\n",
    "Edit every card. A simple rule created the first draft from lines that already contained a definition. Nothing was invented.\n",
  ];
  if (questions.length === 0) {
    lines.push("Q: Add a question\nA: Add an answer\n");
  }
  for (const card of questions) {
    lines.push(`Q: ${card.question}\nA: ${card.answer}\n`);
  }
  lines.push("## Source text\n");
  for (const page of source.pages) lines.push(`### ${page.label}\n\n${page.text.trim()}\n`);
  return lines.join("\n").trim();
}

export function readingNotes(source: TemplateSource) {
  const lines = [sourceBanner(source), "## Source", "", `- Title: ${source.title}`];
  if (source.fileName) lines.push(`- File: ${source.fileName}`);
  lines.push("\n## Quotations\n");
  let quotes = 0;
  for (const page of source.pages) {
    const found = page.text.match(/["“][^"”]{8,}["”]/g) ?? [];
    for (const quote of found) {
      quotes += 1;
      lines.push(`> ${quote}\n>\n> — ${page.label} (${page.method})\n`);
    }
  }
  if (quotes === 0) lines.push("No quoted passages were found. Paste a quotation here.\n");
  lines.push("## Notes and commentary\n");
  for (const page of source.pages) {
    if (!page.text.trim()) continue;
    lines.push(`### ${page.label}\n\n${page.text.trim()}\n\nCommentary:\n`);
  }
  return lines.join("\n").trim();
}

export const STUDY_TEMPLATES = [
  { id: "structured", name: "Structured Lecture Notes", description: "Headings, bullets, and key takeaways copied from the source.", build: structuredLectureNotes },
  { id: "cornell", name: "Cornell Notes", description: "Cue column, notes, and a summary made from existing sentences.", build: cornellNotes },
  { id: "outline", name: "Outline Notes", description: "Hierarchical headings and nested bullets.", build: outlineNotes },
  { id: "study-guide", name: "Study Guide", description: "Terms, topics, and rule-based review prompts.", build: studyGuide },
  { id: "flashcards", name: "Flashcards", description: "Editable question and answer pairs from definition lines.", build: flashcardNotes },
  { id: "reading", name: "Reading Notes", description: "Source details, quotations, and space for commentary.", build: readingNotes },
] as const;

export type StudyTemplateId = (typeof STUDY_TEMPLATES)[number]["id"];

export function applyStudyTemplate(id: StudyTemplateId, source: TemplateSource) {
  const template = STUDY_TEMPLATES.find((item) => item.id === id);
  if (!template) throw new Error("Unknown template");
  return template.build(source);
}

export function parseFlashcards(text: string) {
  const cards: { question: string; answer: string }[] = [];
  const pattern = /Q:\s*([\s\S]*?)\nA:\s*([\s\S]*?)(?=\nQ:|\n## |\s*$)/g;
  for (const match of text.matchAll(pattern)) {
    const question = match[1]?.trim();
    const answer = match[2]?.trim();
    if (question && answer) cards.push({ question, answer });
  }
  return cards;
}

